 'use strict';document.addEventListener('DOMContentLoaded',()=>{if(window.location.search.includes('sent=ok')){setTimeout(()=>showToast('✅ Заявка отправлена!Мы свяжемся с вами в ближайшее время.'),500)}const revealElements=document.querySelectorAll('.reveal');const revealObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}})},{threshold: 0.15,rootMargin: '0px 0px-50px 0px'});revealElements.forEach(el=>revealObserver.observe(el));const header=document.getElementById('header');window.addEventListener('scroll',()=>{header.classList.toggle('scrolled',window.scrollY>50)});const hamburger=document.getElementById('hamburger');const nav=document.getElementById('nav');const navLinks=document.querySelectorAll('.nav__link');function toggleMenu(){const isOpen=nav.classList.toggle('open');hamburger.classList.toggle('active');hamburger.setAttribute('aria-expanded',isOpen);document.body.style.overflow=isOpen ? 'hidden' : ''}function closeMenu(){nav.classList.remove('open');hamburger.classList.remove('active');hamburger.setAttribute('aria-expanded','false');document.body.style.overflow=''}hamburger.addEventListener('click',toggleMenu);navLinks.forEach(link=>{link.addEventListener('click',closeMenu)});const dropdownToggles=document.querySelectorAll('.nav__link--dropdown-toggle');dropdownToggles.forEach(toggle=>{toggle.addEventListener('click',(e)=>{if(window.innerWidth<=768){e.preventDefault();const parent=toggle.closest('.nav__item--dropdown');parent.classList.toggle('open')}})});document.querySelectorAll('.nav__dropdown-link').forEach(link=>{link.addEventListener('click',closeMenu)});document.addEventListener('click',(e)=>{if(nav.classList.contains('open')&&!nav.contains(e.target)&&!hamburger.contains(e.target)){closeMenu()}});document.addEventListener('keydown',(e)=>{if(e.key==='Escape' && nav.classList.contains('open')){closeMenu()}});const statNumbers=document.querySelectorAll('.hero__stat-num[data-count]');const counterObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const el=entry.target;const target=parseInt(el.getAttribute('data-count'),10);animateCounter(el,target);counterObserver.unobserve(el)}})},{threshold: 0.5});statNumbers.forEach(el=>counterObserver.observe(el));function animateCounter(element,target){const duration=2000;const startTime=performance.now();function update(currentTime){const elapsed=currentTime-startTime;const progress=Math.min(elapsed / duration,1);const eased=1-Math.pow(1-progress,3);const current=Math.round(eased * target);if(target>=100){element.textContent=target>=500 ? current : current}else{element.textContent=current}if(progress<1){requestAnimationFrame(update)}else{element.textContent=target>=500 ? target+'+' : target+(target>=100 ? '%' : '')}}requestAnimationFrame(update)}const calcForm=document.getElementById('calcForm');const calcResult=document.getElementById('calcResult');const calcPrice=document.getElementById('calcPrice');const rates={general:{weight: 3.2,volume: 180},equipment:{weight: 4.0,volume: 220},chemicals:{weight: 4.5,volume: 250},food:{weight: 3.8,volume: 200},textile:{weight: 2.8,volume: 150},other:{weight: 3.5,volume: 190}};const cityMult={guangzhou: 1.0,shenzhen: 1.05,shanghai: 1.1,yiwu: 0.95,beijing: 1.15,other: 1.1};const destMult={moscow: 1.0,spb: 1.05,novosibirsk: 0.9,ekb: 0.85,kazan: 0.92,vladivostok: 0.75,other: 0.95};calcForm.addEventListener('submit',(e)=>{e.preventDefault();const cargoType=document.getElementById('cargoType').value;const weight=parseFloat(document.getElementById('weight').value)|| 0;const volume=parseFloat(document.getElementById('volume').value)|| 0;const fromCity=document.getElementById('fromCity').value;const toCity=document.getElementById('toCity').value;if(weight<=0 || volume<=0){showToast('Пожалуйста,укажите вес и объём груза');return}const r=rates[cargoType] || rates.general;const costByWeight=weight * r.weight;const costByVolume=volume * r.volume;const baseCost=Math.max(costByWeight,costByVolume);const fromMult=cityMult[fromCity] || 1.0;const toMult=destMult[toCity] || 1.0;const total=Math.round(baseCost * fromMult * toMult);calcPrice.textContent='$0';calcResult.style.display='block';animatePrice(0,total,1000);setTimeout(()=>{calcResult.scrollIntoView({behavior: 'smooth',block: 'center'})},100)});function animatePrice(from,to,duration){const startTime=performance.now();function update(currentTime){const elapsed=currentTime-startTime;const progress=Math.min(elapsed / duration,1);const eased=1-Math.pow(1-progress,3);const current=Math.round(from+(to-from)* eased);calcPrice.textContent='$'+current.toLocaleString();if(progress<1){requestAnimationFrame(update)}}requestAnimationFrame(update)}const phoneInputs=document.querySelectorAll('input[type="tel"]');phoneInputs.forEach(input=>{input.addEventListener('input',(e)=>{let value=e.target.value.replace(/\D/g,'');if(value.length===0){e.target.value='';return}if(value.startsWith('7')|| value.startsWith('8')){if(value.startsWith('8'))value='7'+value.slice(1)}else{value='7'+value}let formatted='+7';if(value.length>1){formatted+='('+value.slice(1,4)}if(value.length>=5){formatted+=')'+value.slice(4,7)}if(value.length>=8){formatted+='-'+value.slice(7,9)}if(value.length>=10){formatted+='-'+value.slice(9,11)}e.target.value=formatted})});document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',(e)=>{const targetId=anchor.getAttribute('href');if(targetId==='#')return;const target=document.querySelector(targetId);if(target){e.preventDefault();const headerOffset=parseInt(getComputedStyle(document.documentElement).scrollPaddingTop)|| 70;const top=target.getBoundingClientRect().top+window.pageYOffset-headerOffset;window.scrollTo({top,behavior: 'smooth'})}})});function showToast(message){const toast=document.getElementById('toast');if(!toast)return;toast.textContent=message;toast.classList.add('show');if(window._toastTimeout)clearTimeout(window._toastTimeout);window._toastTimeout=setTimeout(()=>{toast.classList.remove('show')},4000)}window.showToast=showToast;const faqItems=document.querySelectorAll('.faq__item');faqItems.forEach(item=>{const question=item.querySelector('.faq__question');const answer=item.querySelector('.faq__answer');question.addEventListener('click',()=>{const isOpen=item.classList.contains('open');faqItems.forEach(other=>{other.classList.remove('open');other.querySelector('.faq__question').setAttribute('aria-expanded','false')});if(!isOpen){item.classList.add('open');question.setAttribute('aria-expanded','true');answer.style.maxHeight=answer.scrollHeight+'px'}else{answer.style.maxHeight='0'}});window.addEventListener('resize',()=>{if(item.classList.contains('open')){answer.style.maxHeight=answer.scrollHeight+'px'}})});console.log('%cТД Кайрос Импорт','font-size: 24px;font-weight: bold;color: #c9a84c;');console.log('%cДоставка грузов из Китая в Россию','font-size: 14px;color: #8a96a8;')});